package com.smartspend;
import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.stereotype.Component;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.web.*;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;import org.springframework.web.filter.OncePerRequestFilter;import java.nio.charset.StandardCharsets;import java.util.*;
@Component class JwtService{byte[] key;long expirationHours;@Value("${app.jwt.secret}")void setSecret(String s){if(s==null||s.length()<32)throw new IllegalStateException("JWT_SECRET must be configured with at least 32 characters");key=s.getBytes(StandardCharsets.UTF_8);}@Value("${app.jwt.expiration-hours:24}")void setExpiry(long h){expirationHours=h;}String create(User u){return Jwts.builder().subject(u.email).claim("role",u.role.name()).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+expirationHours*3600000L)).signWith(Keys.hmacShaKeyFor(key)).compact();}String email(String t){return Jwts.parser().verifyWith(Keys.hmacShaKeyFor(key)).build().parseSignedClaims(t).getPayload().getSubject();}}
@Component class JwtFilter extends OncePerRequestFilter{final JwtService jwt;final UserRepo users;JwtFilter(JwtService j,UserRepo u){jwt=j;users=u;}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws java.io.IOException,ServletException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{User u=users.findByEmail(jwt.email(h.substring(7))).orElse(null);if(u!=null&&u.active)SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.email,null,List.of(new SimpleGrantedAuthority("ROLE_"+u.role))));}catch(Exception ignored){}c.doFilter(r,s);}}
@Configuration @EnableWebSecurity @EnableMethodSecurity class SecurityConfig{final JwtFilter filter;@Value("${app.cors.allowed-origins:http://localhost:5500}")String origins;SecurityConfig(JwtFilter f){filter=f;}@Bean BCryptPasswordEncoder encoder(){return new BCryptPasswordEncoder();}@Bean SecurityFilterChain chain(HttpSecurity h)throws Exception{return h.csrf(x->x.disable()).cors(x->x.configurationSource(r->{var c=new org.springframework.web.cors.CorsConfiguration();c.setAllowedOrigins(Arrays.asList(origins.split(",")));c.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));return c;})).exceptionHandling(e->e.authenticationEntryPoint((req,res,ex)->res.sendError(401,"Unauthorized")).accessDeniedHandler((req,res,ex)->res.sendError(403,"Forbidden"))).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/swagger-ui/**","/v3/api-docs/**","/","/index.html").permitAll().requestMatchers("/api/admin/**").hasRole("ADMIN").anyRequest().authenticated()).addFilterBefore(filter,UsernamePasswordAuthenticationFilter.class).build();}}
